import React from 'react';

const Settings = ({ onBack, settings, onUpdate }) => {
  const languages = [
    { id: 'PT-PT', label: 'Português (EU)' },
    { id: 'EN', label: 'English' },
    { id: 'ES', label: 'Español' },
    { id: 'FR', label: 'Français' },
    { id: 'DE', label: 'Deutsch' }
  ];

  return (
    <div className="min-h-screen bg-raw-onyx text-raw-bone p-8 flex flex-col items-center">
      <div className="max-w-2xl w-full pt-12">
        <div className="flex justify-between items-end mb-12">
          <h1 className="text-6xl font-archivo tracking-tighter">
            CONFIG<span className="text-raw-cyan">.</span>
          </h1>
          <button onClick={onBack} className="text-xs uppercase tracking-[0.3em] opacity-50 hover:opacity-100 transition-opacity mb-2">
            [ Voltar ]
          </button>
        </div>

        <div className="space-y-12">
          <section>
            <h2 className="text-[10px] uppercase tracking-[0.5em] text-raw-bone/30 mb-6 border-b border-raw-bone/10 pb-2">
              Idioma Global
            </h2>
            <div className="grid grid-cols-1 gap-4">
              {languages.map((lang) => (
                <button
                  key={lang.id}
                  onClick={() => onUpdate('language', lang.id)}
                  className={`p-4 border-2 transition-all text-left uppercase font-archivo tracking-widest ${
                    settings.language === lang.id 
                    ? 'border-raw-cyan text-raw-cyan bg-raw-cyan/5' 
                    : 'border-raw-bone/10 text-raw-bone/40 hover:border-raw-bone/30'
                  }`}
                >
                  {lang.label}
                  {settings.language === lang.id && <span className="float-right">SELECTED</span>}
                </button>
              ))}
            </div>
          </section>

          <section>
            <h2 className="text-[10px] uppercase tracking-[0.5em] text-raw-bone/30 mb-6 border-b border-raw-bone/10 pb-2">
              Interface
            </h2>
            <div className="flex justify-between items-center group">
              <div>
                <h3 className="font-archivo text-xl uppercase">Animações de Transição</h3>
                <p className="text-xs opacity-40 italic">Ativa para um feeling mais orgânico.</p>
              </div>
              <button 
                onClick={() => onUpdate('animations', !settings.animations)}
                className={`w-12 h-6 border-2 flex items-center px-1 transition-all ${
                  settings.animations ? 'border-raw-cyan bg-raw-cyan/10' : 'border-raw-bone/20'
                }`}
              >
                <div className={`w-3 h-3 transition-all ${
                  settings.animations ? 'bg-raw-cyan translate-x-6' : 'bg-raw-bone/20'
                }`} />
              </button>
            </div>
          </section>
        </div>
      </div>
    </div>
  );
};

export default Settings;
